CREATE CACHED TABLE "PUBLIC"."MEDIA_PROVIDERS"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "NAME" VARCHAR(128) NOT NULL,
    "DESCRIPTION" CLOB,
    "API_KEY" VARCHAR(512),
    "API_ADDRESS" VARCHAR(512),
    "ENABLED" BOOLEAN DEFAULT TRUE NOT NULL,
    "CREATED_AT" TIMESTAMP(6),
    "UPDATED_AT" TIMESTAMP(6)
);
ALTER TABLE "PUBLIC"."MEDIA_PROVIDERS" ADD CONSTRAINT "PK_MEDIA_PROVIDERS" PRIMARY KEY("ID");

CREATE CACHED TABLE "PUBLIC"."PROVIDER_MODELS"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "PROVIDER_ID" BIGINT NOT NULL,
    "DISPLAY_NAME" VARCHAR(128) NOT NULL,
    "MODEL_ID" VARCHAR(128),
    "SCALE" VARCHAR(64),
    "DESCRIPTION" CLOB,
    "CONCURRENCY" INTEGER DEFAULT 1 NOT NULL,
    "ENABLED" BOOLEAN DEFAULT TRUE NOT NULL
);
ALTER TABLE "PUBLIC"."PROVIDER_MODELS" ADD CONSTRAINT "PK_PROVIDER_MODELS" PRIMARY KEY("ID");
ALTER TABLE "PUBLIC"."PROVIDER_MODELS" ADD CONSTRAINT "FK_PROVIDER_MODELS_PROVIDER" FOREIGN KEY("PROVIDER_ID") REFERENCES "PUBLIC"."MEDIA_PROVIDERS"("ID") ON DELETE CASCADE;
